const bit<16> MYTUNNEL_TYPE = 0x1234;
const bit<16> IPV4_TYPE = 0x800;

typedef bit<9> egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
